from pathlib import Path
import base64, zlib, hashlib

PAYLOAD = r""""""
EXPECTED = "4012ce4ffd82c18bdd1ca9bff3ce20beb40384608e41db4605e69c1a97667749"
root = Path(__file__).resolve().parents[2]
out = root / "multiplayer-deck-master" / "c412.lua"
data = zlib.decompress(base64.b64decode(PAYLOAD))
if hashlib.sha256(data).hexdigest() != EXPECTED:
    raise SystemExit("Attack Guidance Armor payload checksum mismatch")
out.write_bytes(data)
print("Installed Battle Royale Attack Guidance Armor")
